INPUT   P: list of clause pieces over variables 0..n-1
OUTPUT  certificate (A, A*, transport, equinumerous, parities)

function ASSEMBLY-SPACE(P, n):
    A <- empty set
    for each a in {0,1}^n:                      // 2^n iterations
        happy <- true
        for each clause piece c in P:
            if no notch (i,p) in c has a[i] = p:
                happy <- false; break
        if happy: A <- A union {a}
    return A

function COMPLEMENT-PUZZLE(P):
    return [ [ (i, NOT p) for (i,p) in c ] for c in P ]

function TRANSPORT-REPORT(P, n):
    A      <- ASSEMBLY-SPACE(P, n)
    Astar  <- ASSEMBLY-SPACE(COMPLEMENT-PUZZLE(P), n)
    sigmaA <- { (NOT a[0], ..., NOT a[n-1]) : a in A }
    assert Astar = sigmaA                       // Exact Transport
    assert |Astar| = |A|                        // equinumerosity
    C <- A union Astar
    assert n = 0 or |C| mod 2 = 0               // Parity Theorem
    assert n = 0 or |A intersect Astar| mod 2 = 0
    return (A, Astar, C)

INPUT   S: a finite set of assemblies, complement-stable
OUTPUT  gauge, orbit list, and the verified identity |S| = 2|gauge|

function ORBIT-DECOMPOSITION(S):
    // 1. stability precondition
    for each a in S:
        if sigma(a) not in S: raise error

    // 2. the section: fix the polarity of variable 0
    G <- { a in S : a[0] = true }

    // 3. read off the orbits
    orbits <- [ (g, sigma(g)) : g in G ]

    // 4. verify the partition
    covered <- union over (g,s) in orbits of {g, s}
    assert covered = S            // no omission
    assert |S| = 2 * |G|          // no overlap: disjoint by coordinate 0

    return (G, orbits, "even: 2 x |G| free orbits")

