"""Polarity-Gauge Orbit Decomposition: a witnessed parity certificate.

For a complement-stable set S of assemblies, the gauge
    Gauge(S) = { a in S : a_0 = True }
meets each free complementation orbit {a, sigma(a)} exactly once, so
    S = Gauge(S)  disjoint-union  sigma(Gauge(S)),      |S| = 2 |Gauge(S)|.
This turns parity from an existence statement into an explicit pairing.
"""

from __future__ import annotations

from typing import Dict, Iterable, List, Set, Tuple

Assembly = Tuple[bool, ...]


def comp_assembly(a: Assembly) -> Assembly:
    return tuple(not b for b in a)


def is_stable(S: Set[Assembly]) -> bool:
    """S is complement-stable iff sigma(S) is contained in S."""
    return all(comp_assembly(a) in S for a in S)


def polarity_gauge(S: Iterable[Assembly]) -> Set[Assembly]:
    """Section of the orbit map: fix the polarity of variable 0 to True."""
    return {a for a in S if a[0]}


def orbit_decomposition(S: Set[Assembly]) -> Dict[str, object]:
    """Return the orbit pairing together with the verified identity |S| = 2|G|.

    Cost O(|S|).  Raises if S is not complement-stable.
    """
    if not is_stable(S):
        raise ValueError("orbit decomposition requires a complement-stable set")
    G = polarity_gauge(S)
    pairs: List[Tuple[Assembly, Assembly]] = [(g, comp_assembly(g)) for g in sorted(G)]
    covered: Set[Assembly] = set()
    for g, s in pairs:
        covered |= {g, s}
    return {
        "size": len(S),
        "gauge_size": len(G),
        "orbit_count": len(pairs),
        "orbits": pairs,
        "partitions_S": covered == S,
        "identity_holds": len(S) == 2 * len(G),
        "parity_certificate": "even (2 x %d free orbits)" % len(G),
    }


if __name__ == "__main__":
    S = {(True, True, False), (False, False, True),
         (True, False, False), (False, True, True)}
    report = orbit_decomposition(S)
    for key in ("size", "gauge_size", "orbit_count", "partitions_S",
                "identity_holds", "parity_certificate"):
        print(f"{key:20s} : {report[key]}")
    for g, s in report["orbits"]:          # type: ignore[index]
        print("   orbit:", "".join("1" if b else "0" for b in g),
              "<->", "".join("1" if b else "0" for b in s))

algorithms.pseudocode:
INPUT   S: a subset of the Boolean cube {0,1}^n
OUTPUT  a framed puzzle P_S with assembly space exactly S

function EXCLUSION-PIECE(b):
    // one notch per variable, milled for the opposite of b
    return [ (i, NOT b[i]) for i = 0 .. n-1 ]
    // invariant: this piece snaps into place under a  <=>  a != b

function REALISE(S, n):
    P <- empty list
    for each b in {0,1}^n:
        if b not in S:
            append EXCLUSION-PIECE(b) to P
    return P                       // |P| = 2^n - |S|

function VERIFY(S, n):
    P <- REALISE(S, n)
    assert ASSEMBLY-SPACE(P, n) = S
    assert |P| = 2^n - |S|

algorithms.code:
"""Exclusion-Piece Realisation of a Prescribed Assembly Space.

The exclusion piece E_b has, for each variable i, exactly one notch, milled
for the opposite of b_i.  It therefore snaps into place under a iff a != b:
one clause piece forbids exactly one assembly.  Listing one exclusion piece
per excluded point realises ANY prescribed subset S of the Boolean cube:

    P_S = [ E_b : b not in S ],      A(P_S) = S,      |P_S| = 2^n - |S|.

This is the Complete Expressiveness Theorem in algorithmic form.
"""

from __future__ import annotations

import itertools
from typing import Dict, List, Set, Tuple

Assembly = Tuple[bool, ...]
Notch = Tuple[int, bool]
ClausePiece = List[Notch]
FramedPuzzle = List[ClausePiece]


def cube(n: int) -> List[Assembly]:
    return [tuple(bits) for bits in itertools.product([False, True], repeat=n)]


def exclusion_piece(b: Assembly) -> ClausePiece:
    """E_b: one notch per variable, milled for the opposite of b's choice."""
    return [(i, not bit) for i, bit in enumerate(b)]


def realise(S: Set[Assembly], n: int) -> FramedPuzzle:
    """P_S with A(P_S) = S.  Cost O((2^n - |S|) * n) pieces-times-notches."""
    return [exclusion_piece(b) for b in cube(n) if b not in S]


def verify_realisation(S: Set[Assembly], n: int) -> Dict[str, object]:
    """Round-trip check: build P_S, re-enumerate its assembly space."""
    P = realise(S, n)
    recovered = {a for a in cube(n)
                 if all(any(a[i] == p for (i, p) in piece) for piece in P)}
    return {
        "target_size": len(S),
        "piece_count": len(P),
        "piece_count_formula": 2 ** n - len(S),
        "recovered_equals_target": recovered == S,
    }


def render(P: FramedPuzzle) -> str:
    """Human-readable rendering of a framed puzzle."""
    if not P:
        return "(no clause pieces: every assembly fits)"
    return " AND ".join(
        "(" + " OR ".join(("" if p else "-") + f"x{i}" for (i, p) in piece) + ")"
        for piece in P
    )


if __name__ == "__main__":
    n = 3
    S = {(True, True, False), (False, False, True)}
    print("target S     :", sorted("".join("1" if b else "0" for b in a) for a in S))
    print("realisation  :", render(realise(S, n)))
    for key, value in verify_realisation(S, n).items():
        print(f"{key:26s} : {value}")

