    T <- the first k elements of G
    return T union { sigma(g) : g in T }       // stable, size exactly 2k

function SYNTHESISE(n, 2k):
    S <- STABLE-SET(n, 2k)
    return REALISE(S, n)                       // exclusion pieces

function SPECTRUM-SCAN(n):
    for m = 0 .. 2^n:
        if m is odd:
            record m as impossible             // Parity Theorem
        else:
            P <- SYNTHESISE(n, m)
            assert |A(P) union A(P*)| = m      // achieved exactly

algorithms.code:
"""Even-Count Synthesis via Gauge Doubling.

Realises the "if" half of the Combined Spectrum Theorem: for n >= 1 and any
even 2k <= 2^n, construct a framed puzzle whose combined assembly count is
exactly 2k.  Take k points of the polarity gauge, adjoin their complements to
obtain a complement-stable set S of size 2k, and realise S with exclusion
pieces.  Since S is stable, A(P_S*) = sigma(S) = S, so C(P_S) = S.

Together with the Parity Theorem this shows the achievable combined counts on
n >= 1 variables are PRECISELY the even numbers at most 2^n.
"""

from __future__ import annotations

import itertools
from typing import Dict, List, Set, Tuple

Assembly = Tuple[bool, ...]
Notch = Tuple[int, bool]
FramedPuzzle = List[List[Notch]]


def cube(n: int) -> List[Assembly]:
    return [tuple(bits) for bits in itertools.product([False, True], repeat=n)]


def comp_assembly(a: Assembly) -> Assembly:
    return tuple(not b for b in a)


def gauge_of_cube(n: int) -> List[Assembly]:
    """The 2^(n-1) cube points with variable 0 set to True."""
    return [a for a in cube(n) if a[0]]


def stable_set_of_size(n: int, two_k: int) -> Set[Assembly]:
    """A complement-stable set of prescribed even size 2k <= 2^n."""
    if two_k % 2 or two_k > 2 ** n:
        raise ValueError("size must be even and at most 2^n")
    chosen = gauge_of_cube(n)[: two_k // 2]
    return set(chosen) | {comp_assembly(g) for g in chosen}


def synthesise(n: int, two_k: int) -> FramedPuzzle:
    """A framed puzzle with combined assembly count exactly 2k."""
    S = stable_set_of_size(n, two_k)
    return [[(i, not bit) for i, bit in enumerate(b)] for b in cube(n) if b not in S]


def spectrum_scan(n: int) -> Dict[int, bool]:
    """Verify realisation of every even target, and non-realisation of odds."""
    results: Dict[int, bool] = {}
    for m in range(2 ** n + 1):
        if m % 2:
            results[m] = False              # forbidden by the Parity Theorem
            continue
        P = synthesise(n, m)
        A = {a for a in cube(n)
             if all(any(a[i] == p for (i, p) in c) for c in P)}
        Pc = [[(i, not p) for (i, p) in c] for c in P]
        Ac = {a for a in cube(n)
              if all(any(a[i] == p for (i, p) in c) for c in Pc)}
        results[m] = len(A | Ac) == m
    return results


if __name__ == "__main__":
    for n in (1, 2, 3, 4):
        scan = spectrum_scan(n)
        achieved = sorted(m for m, ok in scan.items() if ok)
        print(f"n = {n}:  achievable combined counts = {achieved}"
              f"   (all even m <= {2 ** n})")

algorithms.pseudocode:
INPUT   P: a d-ary framed puzzle on n >= 1 variables
OUTPUT  pooled space, depth gauge, and the certificate d | |C_d(P)|

function SHIFT-PUZZLE(P, t, d):
    return [ [ (i, (s + t) mod d) for (i,s) in c ] for c in P ]

function POOLED-SPACE(P, n, d):
    C <- empty set
    for t = 0 .. d-1:
        Pt <- SHIFT-PUZZLE(P, t, d)
        for each a in (Z/d)^n:
            if every piece of Pt has a notch (i,s) with a[i] = s:
                C <- C union {a}
    return C                                  // shift-stable

function DIVISIBILITY-CERTIFICATE(P, n, d):
    C <- POOLED-SPACE(P, n, d)
    G <- { a in C : a[0] = 0 }                // the depth gauge
    // bijection gauge x Z/d -> C :  (g,t) |-> g + t
    //   surjective: given a, take t = a[0] and g = a - t
    //   injective : coordinate 0 recovers t, cancelling recovers g
    assert |C| = d * |G|
    assert |C| mod d = 0
    return (C, G, orbits of length d)
